diff --git a/lib/matching/matches-repository.ts b/lib/matching/matches-repository.ts
index 3ede0ef2..936f0252 100644
--- a/lib/matching/matches-repository.ts
+++ b/lib/matching/matches-repository.ts
@@ -66,6 +66,14 @@ export interface CreateMatchInput {
   consumption_estimated?: number | null;
   ballast_distance_nm?: number | null;
   breakeven_tce_usd_per_day?: number | null;
+  /**
+   * When true and a duplicate row already exists (INSERT OR IGNORE no-op), UPDATE the
+   * existing row's computed economics + fit columns with the new values. status and
+   * created_at are never changed. worksheet_json uses COALESCE so a null input does not
+   * erase an existing value. Intended only for persistSessionMatches — not for the
+   * background precompute path which should skip already-computed rows entirely.
+   */
+  refreshComputed?: boolean;
 }

 export interface ListMatchesOptions {
@@ -391,7 +399,7 @@ export function createMatch(db: Database.Database, input: CreateMatchInput): Sto
   }

   if (result.changes === 0) {
-    // Duplicate silently ignored by UNIQUE constraint — return the existing row.
+    // Duplicate silently ignored by UNIQUE constraint — fetch the existing row.
     const existing = db
       .prepare(
         `SELECT * FROM matches
@@ -400,6 +408,51 @@ export function createMatch(db: Database.Database, input: CreateMatchInput): Sto
          LIMIT 1`,
       )
       .get(input.cargo_id, input.vessel_id, user_id, user_id) as StoredMatch | undefined;
+
+    if (input.refreshComputed && existing) {
+      // Refresh computed economics + fit columns on a stale per-session row.
+      // status/created_at are intentionally NOT updated (first-write wins).
+      // worksheet_json uses COALESCE so a null input never erases an existing value.
+      // Columns are added conditionally, mirroring the INSERT migration guards above.
+      const refreshNow = Date.now();
+      const setClauses: string[] = [];
+      const refreshArgs: Array<string | number | null> = [];
+
+      if (hasTceColumns(db)) {
+        setClauses.push('tce_usd_per_day = ?');
+        refreshArgs.push(input.tce_usd_per_day ?? null);
+      }
+      if (hasFreightRateColumns(db)) {
+        setClauses.push('freight_rate_usd_per_mt = ?', 'freight_rate_source = ?');
+        refreshArgs.push(input.freight_rate_usd_per_mt ?? null, input.freight_rate_source ?? null);
+      }
+      if (hasFitColumns(db)) {
+        setClauses.push('fit_percent = ?', 'fit_breakdown = ?');
+        refreshArgs.push(input.fit_percent ?? null, input.fit_breakdown ?? null);
+      }
+      if (hasWorksheetColumn(db)) {
+        setClauses.push('worksheet_json = COALESCE(?, worksheet_json)');
+        refreshArgs.push(input.worksheet_json ?? null);
+      }
+      if (hasConsumptionEstimatedColumn(db)) {
+        setClauses.push('consumption_estimated = ?');
+        refreshArgs.push(input.consumption_estimated ?? null);
+      }
+      if (hasBallastDistanceColumn(db)) {
+        setClauses.push('ballast_distance_nm = ?');
+        refreshArgs.push(input.ballast_distance_nm ?? null);
+      }
+      if (hasBreakevenColumn(db)) {
+        setClauses.push('breakeven_tce_usd_per_day = ?');
+        refreshArgs.push(input.breakeven_tce_usd_per_day ?? null);
+      }
+      setClauses.push('updated_at = ?');
+      refreshArgs.push(refreshNow, existing.id);
+
+      db.prepare(`UPDATE matches SET ${setClauses.join(', ')} WHERE id = ?`).run(...refreshArgs);
+      return getMatch(db, existing.id) as StoredMatch;
+    }
+
     return existing!;
   }

