+/**
+ * B.2 parity test — both match write paths write the same 21 columns.
+ *
+ * Compares:
+ *  Path A: real-matches.ts via buildMatchInsertSql (direct SQL INSERT)
+ *  Path B: compute-matches.ts via createMatch (matches-repository)
+ *
+ * Both paths are exercised with the same pre-computed field values.
+ * We verify that the stored rows agree on all 21 shared columns so
+ * a match renders identically regardless of which writer saved it.
+ */
+import Database from 'better-sqlite3';
+import * as sqliteVec from 'sqlite-vec';
+import { runMigrations } from '../lib/migrations/runner';
+import { allMigrations } from '../lib/migrations';
+import { buildMatchInsertSql, tableHasItemIndexCols } from '../scripts/demo-seed/real-matches';
+import { createMatch } from '../lib/matching/matches-repository';
+
+const PARITY_COLS = [
+  'cargo_id',
+  'vessel_id',
+  'cargo_item_index',
+  'vessel_item_index',
+  'score',
+  'reason',
+  'cargo_type',
+  'load_port',
+  'discharge_port',
+  'laycan_start',
+  'laycan_end',
+  'vessel_dwt',
+  'distance_nm',
+  'tce_usd_per_day',
+  'freight_rate_usd_per_mt',
+  'freight_rate_source',
+  'breakeven_tce_usd_per_day',
+  'fit_percent',
+  'fit_breakdown',
+  'worksheet_json',
+  'reason_structured',
+] as const;
+
+type ParityRow = Record<(typeof PARITY_COLS)[number], unknown>;
+
+function makeDb(): Database.Database {
+  const db = new Database(':memory:');
+  sqliteVec.load(db);
+  runMigrations(db, allMigrations);
+  return db;
+}
+
+const FIXED = {
+  cargo_id: 'cargo-email-001',
+  vessel_id: 'vessel-email-001',
+  cargo_item_index: 0,
+  vessel_item_index: 1,
+  score: 78,
+  reason: 'Strong fit — clean across factors',
+  cargo_type: 'BULK',
+  load_port: 'Rotterdam',
+  discharge_port: 'Singapore',
+  laycan_start: 1_750_000_000_000,
+  laycan_end: 1_750_432_000_000,
+  vessel_dwt: 52_000,
+  distance_nm: 8_450,
+  tce_usd_per_day: 9_200,
+  freight_rate_usd_per_mt: 28.5,
+  freight_rate_source: 'baltic',
+  breakeven_tce_usd_per_day: 5_500,
+  fit_percent: 74,
+  fit_breakdown: JSON.stringify({ fitPercent: 74, components: [], totalWeight: 100, partCargo: false, vesselClass: 'supra', sanctionsPenalty: 0, appliedCap: null, inputs: {} }),
+  worksheet_json: JSON.stringify({ readiness: { verdict: 'ideal', gapDays: 2, openPosition: 'Rotterdam' }, vessel: { dwtSummer: 52_000 }, cargo: { weightMt: 40_000 }, hardFilters: { draft: { pass: true } } }),
+  reason_structured: null,
+};
+
+describe('write-path parity — 21 columns', () => {
+  it('path A (real-matches buildMatchInsertSql) writes all 21 columns', () => {
+    const db = makeDb();
+    const hasIdx = tableHasItemIndexCols(db);
+    const stmt = db.prepare(buildMatchInsertSql(hasIdx));
+    const now = Date.now();
+
+    stmt.run(
+      FIXED.cargo_id, FIXED.vessel_id,
+      ...(hasIdx ? [FIXED.cargo_item_index, FIXED.vessel_item_index] : []),
+      FIXED.score, FIXED.reason,
+      null, now, now,
+      FIXED.cargo_type, FIXED.load_port, FIXED.discharge_port,
+      FIXED.laycan_start, FIXED.laycan_end, FIXED.vessel_dwt,
+      FIXED.tce_usd_per_day, FIXED.distance_nm,
+      FIXED.freight_rate_usd_per_mt, FIXED.freight_rate_source,
+      FIXED.fit_percent, FIXED.fit_breakdown,
+      FIXED.worksheet_json, FIXED.reason_structured,
+      FIXED.breakeven_tce_usd_per_day,
+    );
+
+    const row = db.prepare('SELECT * FROM matches WHERE cargo_id = ?').get(FIXED.cargo_id) as ParityRow;
+    expect(row).not.toBeNull();
+
+    for (const col of PARITY_COLS) {
+      if (col === 'reason_structured') {
+        expect(row[col]).toBeNull();
+        continue;
+      }
+      expect(row[col]).not.toBeNull();
+      expect(row[col]).toBe((FIXED as Record<string, unknown>)[col]);
+    }
+  });
+
+  it('path B (createMatch) writes all 21 columns', () => {
+    const db = makeDb();
+
+    createMatch(db, {
+      cargo_id: FIXED.cargo_id,
+      vessel_id: FIXED.vessel_id,
+      cargo_item_index: FIXED.cargo_item_index,
+      vessel_item_index: FIXED.vessel_item_index,
+      score: FIXED.score,
+      reason: FIXED.reason,
+      status: 'shortlist',
+      user_id: null,
+      cargo_type: FIXED.cargo_type,
+      load_port: FIXED.load_port,
+      discharge_port: FIXED.discharge_port,
+      laycan_start: FIXED.laycan_start,
+      laycan_end: FIXED.laycan_end,
+      vessel_dwt: FIXED.vessel_dwt,
+      distance_nm: FIXED.distance_nm,
+      tce_usd_per_day: FIXED.tce_usd_per_day,
+      freight_rate_usd_per_mt: FIXED.freight_rate_usd_per_mt,
+      freight_rate_source: FIXED.freight_rate_source,
+      breakeven_tce_usd_per_day: FIXED.breakeven_tce_usd_per_day,
+      fit_percent: FIXED.fit_percent,
+      fit_breakdown: FIXED.fit_breakdown,
+      worksheet_json: FIXED.worksheet_json,
+      reason_structured: FIXED.reason_structured,
+    });
+
+    const row = db.prepare('SELECT * FROM matches WHERE cargo_id = ?').get(FIXED.cargo_id) as ParityRow;
+    expect(row).not.toBeNull();
+
+    for (const col of PARITY_COLS) {
+      if (col === 'reason_structured') {
+        expect(row[col]).toBeNull();
+        continue;
+      }
+      expect(row[col]).not.toBeNull();
+      expect(row[col]).toBe((FIXED as Record<string, unknown>)[col]);
+    }
+  });
+
+  it('both paths produce identical values for all 21 columns', () => {
+    const dbA = makeDb();
+    const dbB = makeDb();
+    const now = Date.now();
+
+    // Path A
+    const hasIdx = tableHasItemIndexCols(dbA);
+    dbA.prepare(buildMatchInsertSql(hasIdx)).run(
+      FIXED.cargo_id, FIXED.vessel_id,
+      ...(hasIdx ? [FIXED.cargo_item_index, FIXED.vessel_item_index] : []),
+      FIXED.score, FIXED.reason,
+      null, now, now,
+      FIXED.cargo_type, FIXED.load_port, FIXED.discharge_port,
+      FIXED.laycan_start, FIXED.laycan_end, FIXED.vessel_dwt,
+      FIXED.tce_usd_per_day, FIXED.distance_nm,
+      FIXED.freight_rate_usd_per_mt, FIXED.freight_rate_source,
+      FIXED.fit_percent, FIXED.fit_breakdown,
+      FIXED.worksheet_json, FIXED.reason_structured,
+      FIXED.breakeven_tce_usd_per_day,
+    );
+    const rowA = dbA.prepare('SELECT * FROM matches WHERE cargo_id = ?').get(FIXED.cargo_id) as ParityRow;
+
+    // Path B
+    createMatch(dbB, {
+      cargo_id: FIXED.cargo_id,
+      vessel_id: FIXED.vessel_id,
+      cargo_item_index: FIXED.cargo_item_index,
+      vessel_item_index: FIXED.vessel_item_index,
+      score: FIXED.score,
+      reason: FIXED.reason,
+      status: 'shortlist',
+      user_id: null,
+      cargo_type: FIXED.cargo_type,
+      load_port: FIXED.load_port,
+      discharge_port: FIXED.discharge_port,
+      laycan_start: FIXED.laycan_start,
+      laycan_end: FIXED.laycan_end,
+      vessel_dwt: FIXED.vessel_dwt,
+      distance_nm: FIXED.distance_nm,
+      tce_usd_per_day: FIXED.tce_usd_per_day,
+      freight_rate_usd_per_mt: FIXED.freight_rate_usd_per_mt,
+      freight_rate_source: FIXED.freight_rate_source,
+      breakeven_tce_usd_per_day: FIXED.breakeven_tce_usd_per_day,
+      fit_percent: FIXED.fit_percent,
+      fit_breakdown: FIXED.fit_breakdown,
+      worksheet_json: FIXED.worksheet_json,
+      reason_structured: FIXED.reason_structured,
+    });
+    const rowB = dbB.prepare('SELECT * FROM matches WHERE cargo_id = ?').get(FIXED.cargo_id) as ParityRow;
+
+    for (const col of PARITY_COLS) {
+      expect(rowA[col]).toStrictEqual(rowB[col]);
+    }
+  });
+});
